  componentDidMount() { this.wire(); }
  componentDidUpdate() { this.wire(); }

  wire() {
    const root = this.root;
    if (!root || this.wired) return;
    const input = root.querySelector('[data-filter]');
    if (!input) return;
    this.wired = true;
    const status = root.querySelector('[data-status]');
    const clear = root.querySelector('[data-clear]');
    const empty = root.querySelector('[data-empty]');
    const bar = root.querySelector('[data-filterbar]');
    const jump = root.querySelector('[data-jump]');
    const groups = Array.from(root.querySelectorAll('[data-grp]'));
    const links = Array.from(root.querySelectorAll('[data-link]'));
    const total = links.length;
    const startOpen = this.props.sectionsOpen === true;

    if (this.props.showFilter === false && bar) bar.style.display = 'none';

    const sync = (d) => {
      const m = d.querySelector('[data-mark]');
      if (m) m.textContent = d.open ? '\u2212' : '+';
    };
    groups.forEach(g => {
      const c = g.querySelector('[data-count]');
      if (c) c.textContent = g.querySelectorAll('[data-link]').length + ' pages';
      g.open = startOpen;
      sync(g);
      g.addEventListener('toggle', () => sync(g));
    });
    if (jump) {
      const jm = jump.querySelector('[data-jumpmark]');
      const jsync = () => { if (jm) jm.textContent = jump.open ? '\u2212' : '+'; };
      jump.addEventListener('toggle', jsync);
      jsync();
      jump.querySelectorAll('[data-chip]').forEach(a => {
        a.addEventListener('click', () => {
          const t = root.querySelector(a.getAttribute('href'));
          if (t) t.open = true;
          if (t) sync(t);
        });
      });
    }

    const apply = () => {
      const q = (input.value || '').trim().toLowerCase();
      let hits = 0;
      links.forEach(a => {
        const match = !q || a.textContent.toLowerCase().indexOf(q) !== -1;
        a.parentElement.style.display = match ? '' : 'none';
        if (match) hits++;
      });
      groups.forEach(g => {
        const visible = Array.from(g.querySelectorAll('[data-link]')).filter(a => a.parentElement.style.display !== 'none');
        g.style.display = visible.length ? '' : 'none';
        const c = g.querySelector('[data-count]');
        if (c) c.textContent = visible.length + ' pages';
        if (q) { g.open = true; } else { g.open = startOpen; }
        sync(g);
      });
      if (empty) empty.style.display = hits ? 'none' : '';
      if (clear) clear.style.display = q ? '' : 'none';
      if (status) status.textContent = q
        ? (hits === 0 ? 'No page matches \u201C' + input.value.trim() + '\u201D' : hits + (hits === 1 ? ' page matches ' : ' pages match ') + '\u201C' + input.value.trim() + '\u201D')
        : total + ' links in 11 sections — tap a section to open it';
    };
    input.addEventListener('input', apply);
    if (clear) clear.addEventListener('click', () => { input.value = ''; apply(); input.focus(); });
    apply();
  }
